(async () => {
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  const found = () => JSON.stringify({
    url: location.href,
    err: (Array.from(document.querySelectorAll('div,span,p,label')).map(e=>(e.innerText||'').trim()).filter(t=>/invalid|incorrect|error|wrong|expired|failed/i.test(t) && t.length<90).slice(0,5)),
    inputs: Array.from(document.querySelectorAll('input')).map(i=>({id:i.id, type:i.type, vis: i.offsetParent!==null, maxLen:i.maxLength})).filter(i=>/first|second|third|fourth|fifth|sixth|otp|pin/i.test(i.id||'')||i.maxLen===1||i.maxLen===4).slice(0,12)
  });
  const c = Array.from(document.querySelectorAll('button')).find(b => /Confirm\s*OTP/i.test(b.innerText||''));
  if (c) { c.click(); await sleep(1200); }
  let boxes = Array.from(document.querySelectorAll('input[type=number],input[type=tel],input[type=text]'))
    .filter(i => /^(first|second|third|fourth|fifth|sixth)$/.test(i.id||'') || ((i.maxLength===1 || i.maxLength===4) && i.offsetParent!==null && i.type==='number'));
  if (!boxes.length) boxes = Array.from(document.querySelectorAll('input[type=number]')).filter(i=>i.offsetParent!==null);
  if (boxes.length) {
    const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
    const digits = '8751';
    for (let i = 0; i < boxes.length; i++) {
      setter.call(boxes[i], i < digits.length ? digits[i] : '');
      boxes[i].dispatchEvent(new Event('input', {bubbles:true}));
      boxes[i].dispatchEvent(new Event('change', {bubbles:true}));
    }
    await sleep(400);
    const c2 = Array.from(document.querySelectorAll('button')).find(b => /Confirm\s*OTP/i.test(b.innerText||''));
    if (c2) { c2.click(); await sleep(9000); }
    return found();
  }
  return JSON.stringify({stage:'noBoxesStill', ...JSON.parse(found())});
})()
